entity_group.select:
SELECT * FROM (
            SELECT reference_entity_key AS group_key, 'reference' AS kind, entity_id FROM {entity}
            UNION ALL SELECT unnest(gene_reference_keys), 'gene', entity_id FROM {entity}
            UNION ALL SELECT group_connectivity, 'connectivity', entity_id FROM {entity}
        ) WHERE group_key IS NOT NULL

entity_term.select:
SELECT DISTINCT term, kind, entity_id FROM (
            SELECT lower(label) AS term, 'label' AS kind, entity_id FROM {entity}
            UNION ALL SELECT lower(identifier), 'identifier', entity_id FROM {entity}
            UNION ALL SELECT lower(id), 'identifier', entity_id FROM {entity_identifier}
        ) WHERE term IS NOT NULL AND term <> ''
